<script setup lang="ts">
import {onBeforeUnmount,onMounted,watch} from 'vue';
import type {ApiClient,EscrowWalletRefund} from '@kuaixie/sdk';
import {t,formatAmount,formatDate} from '@kuaixie/i18n';
import {useEscrowRefunds} from './useEscrowRefunds';
const props=defineProps<{client:ApiClient;admin?:boolean;caseId:string;orderId?:string;role?:string;record?:EscrowWalletRefund|null}>();
const emit=defineEmits<{locked:[value:boolean];recorded:[]}>();
const p=useEscrowRefunds(props.client,async(title,body)=>window.confirm(title+'\n'+body),{admin:!!props.admin,caseId:()=>props.caseId,orderId:()=>props.orderId||'',role:()=>props.role||(props.admin?'operator':'buyer'),seed:()=>props.record||null});
watch(p.locked,value=>emit('locked',value),{immediate:true});watch(()=>p.receipt.value?.id,(id,old)=>{if(id&&id!==old)emit('recorded')});onBeforeUnmount(()=>emit('locked',false));
onMounted(()=>{if(!props.admin&&(props.role||'buyer')==='buyer')void p.loadRecords()});
</script>
<template><section class="escrow-panel"><h3>{{t('escrowRefund.title')}}</h3><p class="destination">{{t('escrowRefund.destinationNotice')}}</p><p v-if="p.error.value" role="alert">{{p.error.value}}</p><p v-if="p.notice.value" role="status">{{p.notice.value}}</p><template v-if="admin"><button :disabled="p.busy.value||p.confirming.value||p.loading.value" @click="p.loadBudget()">{{t('escrowRefund.readBudget')}}</button><p v-if="p.loading.value">{{t('account.loading')}}</p><article v-if="p.budget.value?.status==='blocked'"><strong>{{t('escrowRefund.blocked')}}</strong><p>{{t('escrowRefund.blockedHelp')}}</p><code>{{p.budget.value.reasonCode}}</code></article><article v-if="p.eligible.value"><h4>{{t('escrowRefund.budget')}}</h4><dl><dt>{{t('escrowRefund.order')}}</dt><dd>{{p.eligible.value.orderId}}</dd><dt>{{t('escrowRefund.originalGoods')}}</dt><dd>{{formatAmount(p.eligible.value.goodsAmount,'CNY')}}</dd><dt>{{t('escrowRefund.previouslyRefunded')}}</dt><dd>{{formatAmount(p.eligible.value.alreadyRefunded,'CNY')}}</dd><dt>{{t('escrowRefund.remainingGoods')}}</dt><dd>{{formatAmount(p.eligible.value.refundableGoods,'CNY')}}</dd><dt>{{t('escrowRefund.requestedAmount')}}</dt><dd>{{formatAmount(p.eligible.value.requestedAmount,'CNY')}}</dd><dt>{{t('escrowRefund.heldEscrow')}}</dt><dd>{{formatAmount(p.eligible.value.buyerEscrowHeld,'CNY')}}</dd><dt>{{t('escrowRefund.heldServiceFee')}}</dt><dd>{{formatAmount(p.eligible.value.serviceFeeHeld,'CNY')}}</dd><dt>{{t('escrowRefund.heldShipping')}}</dt><dd>{{formatAmount(p.eligible.value.shippingHeld,'CNY')}}</dd></dl><p>{{t('escrowRefund.excludedFees')}}</p><p v-if="p.eligible.value.requiresAccounting">{{t('escrowRefund.fullAccounting')}}</p><p>{{t('escrowRefund.rewardReview')}}</p><fieldset :disabled="p.locked.value||p.loading.value"><label>{{t('escrowRefund.note')}}<textarea v-model="p.note.value" maxlength="200"/></label><button :disabled="!p.canExecute.value" @click="p.execute()">{{t('escrowRefund.execute')}}</button></fieldset></article><article v-if="p.pending.value"><p>{{t('escrowRefund.unconfirmed')}}</p><p>{{t('escrowRefund.pendingCase')}} {{p.pending.value.caseId}}</p><p>{{formatAmount(p.pending.value.amount,'CNY')}}</p><button :disabled="p.busy.value||p.loading.value" @click="p.loadBudget()">{{t('escrowRefund.reconcile')}}</button><button v-if="p.retryAllowed.value" :disabled="p.busy.value||p.loading.value" @click="p.retry()">{{t('escrowRefund.retryOriginal')}}</button></article></template><article v-if="p.receipt.value"><h4>{{t('escrowRefund.receipt')}}</h4><p>{{formatAmount(p.receipt.value.amount,'CNY')}} · {{formatDate(p.receipt.value.createdAt)}}</p><p>{{p.receipt.value.id}}</p><p v-if="p.receipt.value.requiresAccounting">{{t('escrowRefund.fullAccounting')}}</p><p>{{t('escrowRefund.rewardReview')}}</p><button v-if="p.canReadEvents.value" :disabled="p.eventsLoading.value" @click="p.loadEvents(p.receipt.value.id)">{{t('escrowRefund.events')}}</button></article><p v-else-if="!admin">{{t('escrowRefund.noCaseReceipt')}}</p><details v-if="!admin&&(role||'buyer')==='buyer'"><summary>{{t('escrowRefund.history')}}</summary><button :disabled="p.recordsLoading.value" @click="p.loadRecords()">{{t('escrowRefund.refresh')}}</button><p v-if="!p.recordsLoading.value&&!p.records.value.length">{{t('escrowRefund.noRecords')}}</p><article v-for="row in p.records.value" :key="row.id"><strong>{{formatAmount(row.amount,'CNY')}}</strong><p>{{t('escrowRefund.order')}} {{row.orderId}} · {{formatDate(row.createdAt)}}</p><p>{{t('escrowRefund.receipt')}} {{row.id}}</p><button :disabled="p.eventsLoading.value" @click="p.loadEvents(row.id)">{{t('escrowRefund.events')}}</button></article><button v-if="p.more.value" :disabled="p.recordsLoading.value" @click="p.loadRecords(true)">{{t('escrowRefund.more')}}</button></details><section v-if="p.eventsId.value"><h4>{{t('escrowRefund.events')}} · {{p.eventsId.value}}</h4><p v-if="p.eventsLoading.value">{{t('account.loading')}}</p><p v-if="!p.eventsLoading.value&&!p.events.value.length">{{t('escrowRefund.noEvents')}}</p><article v-for="event in p.events.value" :key="event.id"><strong>{{t(event.action==='wallet_refunded'?'escrowRefund.walletRecorded':'escrowRefund.eventRecorded')}}</strong><p>{{formatDate(event.createdAt)}}</p><p v-if="admin">{{event.detail}}</p></article><button v-if="p.moreEvents.value" :disabled="p.eventsLoading.value" @click="p.loadEvents(p.eventsId.value,true)">{{t('escrowRefund.more')}}</button></section></section></template>
<style scoped>.escrow-panel{padding:18px;border:1px solid #cbd5e1;border-radius:10px;margin-top:18px}.escrow-panel p{line-height:1.7;overflow-wrap:anywhere}.escrow-panel .destination{padding:12px;background:#eff6ff;color:#1e3a5f;border-radius:8px}.escrow-panel dl{display:grid;grid-template-columns:1fr 1fr;gap:10px}.escrow-panel dd{margin:0;text-align:right;overflow-wrap:anywhere}.escrow-panel fieldset{border:0;padding:0;display:grid;gap:12px}.escrow-panel label{display:grid;gap:7px}.escrow-panel textarea{max-width:100%;box-sizing:border-box;min-height:70px}.escrow-panel button{padding:9px;margin:6px 6px 6px 0}.escrow-panel article{border-top:1px solid #e2e8f0;margin-top:12px;padding-top:12px}.escrow-panel [role=alert]{color:#b42318}</style>
